# `shoehorn`

```
npm i @total-typescript/shoehorn
```

`shoehorn` (meaning "to force something into a space") lets you **pass partial data in tests** while keeping TypeScript happy.

### Problem

Using 'as' in tests feels bad.

```ts
type Request = {
  body: {
    id: string;
  };
  // Imagine oodles of other properties...
};

it("Should get the user", () => {
  // Even though we only care about body.id for
  // this test, we need to pass in the whole Request
  // object
  getUser({
    body: {
      id: "123",
    },
  } as Request);
});
```

- You're trained not to use it
- You need to _manually_ specify the type you want to assert to
- For testing with incorrect data, you need to 'double-as' (`as unknown as User`)

### Solution

`shoehorn` gives you some first-class primitives for _safely_ providing incomplete data to tests.

```ts
import { fromPartial } from "@total-typescript/shoehorn";

it("Should get the user", () => {
  getUser(
    fromPartial({
      body: {
        id: "123",
      },
    }),
  );
});
```

### But isn't passing partial data to tests bad?

Yes, in general. Having to pass huge objects to tests is a sign that your types are too loose. Ideally, every function should only specify the data it needs.

Unfortunately, we live in the real world. There are many cases where `shoehorn` is the best choice:

- **Legacy codebases**: If you're working on a large codebase, you might not have the time to refactor everything to be perfect.
- **Third-party libraries**: If you're using a third-party library, you might not be able to alter the types without needless wrapper functions.

## API

For each example below, imagine that the following types are defined:

```ts
type Request = {
  body: {
    id: string;
  };
  // Imagine oodles of other properties...
};

// The function we're testing
const requiresRequest = (request: Request) => {};
```

### `fromPartial`

Lets you pass a deep partial to a slot expecting a type.

```ts
import { fromPartial } from "@total-typescript/shoehorn";

requiresRequest(
  fromPartial({
    body: {
      id: "123",
    },
  }),
);
```

It'll fail if you pass a type that doesn't match the one expected:

```ts
// Type "1234123" has no properties in common
// with type 'PartialObjectDeep<Request>'
requiresRequest(fromPartial("1234123"));
```

### `fromAny`

Lets you pass anything to a slot, while still giving you autocomplete on the original type:

```ts
import { fromAny } from "@total-typescript/shoehorn";

requiresRequest(
  fromAny({
    body: {
      id: 124123,
    },
  }),
);
```

It WILL NOT FAIL if you pass something that doesn't match.

```ts
// All good!
requiresRequest(fromAny("1234123"));
```

### `fromExact`

A convenience method for forcing you to pass all the properties of a type. Useful for when you want to swap in and out of `fromPartial`/`fromAny`:

```ts
import { fromExact } from "@total-typescript/shoehorn";

requiresRequest(
  // Will fail! We're not passing all the oodles of
  // properties of Request
  fromExact({
    body: {
      id: 124123,
    },
  }),
);
```

import { describe, expect, it } from "vitest";
import { fromAny, fromExact, fromPartial } from "../src";
import { Equal, Expect, accept } from "./test-utils";

describe("fromExact", () => {
  it("Should return whatever you pass in", () => {
    const result = fromExact({ foo: "bar" });

    expect(result).toEqual({ foo: "bar" });
  });

  it("Should return the type you pass in", () => {
    const result = fromExact({ foo: "bar" });

    type test = Expect<Equal<typeof result, { foo: string }>>;
  });

  it("When passed to a function, it should expect the exact type", () => {
    accept<{ foo: string; bar: number }>(
      // @ts-expect-error
      fromExact({
        foo: "bar",
      }),
    );
  });
});

import { describe, expect, it } from "vitest";
import { Equal, Expect, accept } from "./test-utils";
import { fromAny } from "../src";

describe("fromAny", () => {
  it("Should return whatever you pass in", () => {
    const result = fromAny({ foo: "bar" });

    expect(result).toEqual({ foo: "bar" });
  });

  it("Should return unknown if not called in a function's args", () => {
    const result = fromAny({ foo: "bar" });

    type test = Expect<Equal<typeof result, unknown>>;
  });

  it("Should let you pass anything to a function", () => {
    accept<{ foo: string; bar: number }>(fromAny("str"));

    accept<{ foo: string; bar: number }>(fromAny(124123));

    accept<{ foo: string; bar: number }>(
      fromAny({
        foo: "awdaw",
      }),
    );
  });

  it("When passed into a function, it should NOT give excess property warnings", () => {
    accept<{
      foo: string;
      bar: number;
    }>(
      fromAny({
        foo: "bar",
        baz: 1,
      }),
    );
  });
});

import { describe, expect, it } from "vitest";
import { fromPartial } from "../src";
import { Equal, Expect, accept } from "./test-utils";

describe("fromPartial", () => {
  it("Should return whatever you pass in", () => {
    const result = fromPartial({ foo: "bar" });

    expect(result).toEqual({ foo: "bar" });
  });

  it("When not passed into a function, it should return unknown", () => {
    const result = fromPartial({ foo: "bar" });

    type test = Expect<Equal<typeof result, unknown>>;
  });

  it("When passed a type argument, it should let you pass a partial of the type", () => {
    const result = fromPartial<{ foo: string; bar: string }>({
      foo: "str",
    });

    type test = Expect<Equal<typeof result, { foo: string; bar: string }>>;
  });

  it("When passed into a function, it should let you pass a partial", () => {
    accept<{
      foo: string;
      bar: number;
    }>(
      fromPartial({
        foo: "bar",
      }),
    );
  });

  it("When passed into a function, it should let you pass a deep partial", () => {
    accept<{
      foo: string;
      bar: {
        baz: number;
      };
      arr: {
        id: number;
        name: string;
      }[];
    }>(
      fromPartial({
        foo: "bar",
        bar: {},
        arr: [{ id: 1 }],
      }),
    );
  });

  it("When passed into a function, it should give excess property warnings", () => {
    accept<{
      foo: string;
      bar: number;
    }>(
      fromPartial({
        foo: "bar",
        // @ts-expect-error
        baz: 1,
      }),
    );
  });

  it("Should accept functions", () => {
    accept<() => void>(fromPartial({}));
  });

  it("Should accept interfaces which combine object properties and a call signature", () => {
    accept<{
      (): void;
      foo: string;
    }>(fromPartial({}));
  });

  it("Should make interfaces which combined object properties and call signatures deeply partial", () => {
    accept<{
      (): void;
      foo: {
        deepProperty: string;
      };
    }>(
      fromPartial({
        foo: {},
      }),
    );
  });
});

export type Expect<T extends true> = T;
export type ExpectTrue<T extends true> = T;
export type ExpectFalse<T extends false> = T;
export type IsTrue<T extends true> = T;
export type IsFalse<T extends false> = T;

export type Equal<X, Y> = (<T>() => T extends X ? 1 : 2) extends <
  T,
>() => T extends Y ? 1 : 2
  ? true
  : false;
export type NotEqual<X, Y> = true extends Equal<X, Y> ? false : true;

// https://stackoverflow.com/questions/49927523/disallow-call-with-any/49928360#49928360
export type IsAny<T> = 0 extends 1 & T ? true : false;
export type NotAny<T> = true extends IsAny<T> ? false : true;

export type Debug<T> = { [K in keyof T]: T[K] };
export type MergeInsertions<T> = T extends object
  ? { [K in keyof T]: MergeInsertions<T[K]> }
  : T;

export type Alike<X, Y> = Equal<MergeInsertions<X>, MergeInsertions<Y>>;

export type ExpectExtends<VALUE, EXPECTED> = EXPECTED extends VALUE
  ? true
  : false;
export type ExpectValidArgs<
  FUNC extends (...args: any[]) => any,
  ARGS extends any[],
> = ARGS extends Parameters<FUNC> ? true : false;

export type UnionToIntersection<U> = (
  U extends any ? (k: U) => void : never
) extends (k: infer I) => void
  ? I
  : never;

export const doNotExecute = (func: () => any) => {};

export const accept = <T>(_t: T) => {};

